#include <bitset>
#include <stdexcept>
#include <iostream>

void convert(const std::bitset<100>& bs) {
    try {
        // Will likely throw if bits > 64 are set
        unsigned long val = bs.to_ulong(); 
        std::cout << "Converted: " << val << "\n";
    } catch (const std::overflow_error& e) {
        std::cerr << "Error: " << e.what() << " (Value too large)\n";
    }
}

int main() {
    // 100-bit bitset, value 555
    std::bitset<100> bs(std::string("1000101011")); 
    convert(bs);

    // Example that guarantees overflow if ULLONG is 64 bits
    std::bitset<70> large_bs;
    large_bs.set(65); // Set a bit beyond standard ULLONG range
    // convert(large_bs); // Would throw if uncommented
}
